head.script:
scwin.checkedMenuIds = [];

scwin.onpageload = function () {
    console.log("메뉴-그룹 권한 관리 시작!!!!");

    dmp_selectedGroup.set("selectedGrpId", "");
    dmp_selectedGroup.set("selectedGrpName", "선택된 그룹 없음");

    $c.sbm.execute($p, sbm_selectGroupsVoList);
    $c.sbm.execute($p, sbm_selectMenuVoList);
};

scwin.sbm_selectGroupsVoList_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert("그룹 목록 조회 실패: " + (elHeader ? elHeader.resMsg : "오류"));
        return;
    }

    console.log("그룹 목록 조회 완료:", dlt_groupsVoList.getTotalRow() + "개");
};

scwin.sbm_selectMenuVoList_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;
    var elData = e.responseJSON.elData;
    console.log(elData);

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert("메뉴 목록 조회 실패: " + (elHeader ? elHeader.resMsg : "오류"));
        return;
    }
    dlt_menuVoList.setJSON(elData.menuVoList);
    for (let i = 0; i < dlt_menuVoList.getTotalRow(); i++) {
        dlt_menuVoList.setCellData(i, "checked", "false");
    }

    console.log("전체 메뉴 목록 조회 완료:", dlt_menuVoList.getTotalRow() + "개");
};

scwin.sbm_selectGroupMenuList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        console.log("그룹 메뉴 권한 조회 실패:", elHeader ? elHeader.resMsg : "오류");
        scwin.checkedMenuIds = [];
        return;
    }

    console.log("그룹 메뉴 권한 조회 완료:", elData);

    scwin.checkedMenuIds = [];
    if (elData.menuVoList && elData.menuVoList.length > 0) {
        scwin.checkedMenuIds = elData.menuVoList.map(item => item.menuId);
    }

    for (let i = 0; i < dlt_menuVoList.getTotalRow(); i++) {
        let menuId = dlt_menuVoList.getCellData(i, "menuId");
        let shouldCheck = scwin.checkedMenuIds.includes(menuId);
        dlt_menuVoList.setCellData(i, "checked", shouldCheck ? "true" : "false");
    }
};

scwin.sbm_saveGroupMenu_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert("저장 실패: " + (elHeader ? elHeader.resMsg : "오류"));
        return;
    }

    $c.win.alert("메뉴 권한이 저장되었습니다.");
    console.log("저장 완료");
};

scwin.gridView_oncellclick = function (rowIndex, columnIndex, columnId) {
    scwin.selectGroup(rowIndex);
};

scwin.selectGroup = function(rowIndex) {
    let selectedRow = dlt_groupsVoList.getRowJSON(rowIndex);
    let grpId = selectedRow.grpId;
    let grpName = selectedRow.grpName;

    dmp_selectedGroup.set("selectedGrpId", grpId);
    dmp_selectedGroup.set("selectedGrpName", grpName);

    gridView.setFocusedCell(rowIndex, 0, false);

    dmp_menuVo.set("grpId", grpId);
    $c.sbm.execute($p, sbm_selectGroupMenuList);

    console.log("그룹 선택:", grpId, grpName);
};

// 수정된 체크박스 클릭 이벤트 - getCheckedValues() API 사용
scwin.treeview_oncheckboxclick = function(value, node, index) {
    console.log("체크박스 변경:", value, node.checked ? "체크" : "해제");

    // 약간의 지연 후 실제 체크된 모든 값들을 가져옴 (checkAllChildNodes 처리 완료 후)
    setTimeout(function() {
        scwin.checkedMenuIds = treeview.getCheckedValues();
        console.log("현재 체크된 모든 메뉴들:", scwin.checkedMenuIds);
    }, 50);
};

// 수정된 저장 버튼 - 저장 직전에 최신 체크 상태 반영
scwin.btn_save_onclick = function(e) {
    let selectedGrpId = dmp_selectedGroup.get("selectedGrpId");

    if (!selectedGrpId || selectedGrpId === "") {
        $c.win.alert("먼저 그룹을 선택해주세요.");
        return;
    }

    // 저장 직전에 실제 체크된 값들을 다시 가져옴 (확실하게!)
    scwin.checkedMenuIds = treeview.getCheckedValues();

    let menuList = scwin.checkedMenuIds.map(menuId => ({
        menuId: menuId,
        grpId: selectedGrpId
    }));

    console.log("저장할 메뉴 (부모+하위 모두 포함):", menuList);

    let reqObj = {
        "elData": { "menuVoList": menuList }
    };

    $c.sbm.execute($p, sbm_saveGroupMenu, reqObj);
};

// 수정된 새로고침 버튼 - reqObj 오류 수정
scwin.btn_refresh_onclick = function(e) {
    let selectedGrpId = dmp_selectedGroup.get("selectedGrpId");

    if (selectedGrpId) {
        dmp_menuVo.set("grpId", selectedGrpId);
        $c.sbm.execute($p, sbm_selectGroupMenuList);
    }
};

// 돌아가기 버튼 이벤트
scwin.btn_return_onclick = function (e) {
    WebSquare.localStorage.removeItem("adminPage");
    $p.url("/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/ui/testMain.xml");
};
